/* runtime.js -- THE one JS file (RFC-001 §4.0/§4.2), written once.
 *
 * The framework's browser half. A lesson ships: lesson.json (all
 * structure and pedagogy as data), notes.html (prose), lesson.wasm (the
 * physics, via lessons-common's uniform ABI), and a ~15-line HTML stub.
 * This file does the rest: builds the page scaffold from the manifest
 * (header, claims, stages, transport bar, legend, notes, try-this,
 * footer), generates every control and readout, owns the clock, writes
 * params into wasm memory, and paints the primitive buffer back.
 *
 * Uniform wasm ABI (generated by lessons-common::lesson!):
 *   params_ptr() -> f64*     runtime writes params, manifest order
 *   state_at(n) -> len       recompute; pure over the params
 *   prims_ptr(), readouts_ptr()
 *
 * Prim records: [0,x,y,st] point · [1,x1,y1,x2,y2,st] segment ·
 * [2,n,pts...,st] polyline · [3,...] arrow · [9,view] view switch.
 * Geometry views must scale both axes alike (the skew guard throws); a
 * view may declare "uniform": false only where its axes carry different
 * quantities (a phase portrait, a graph) -- a statement, not an escape.
 */
"use strict";

function fatal(title, detail) {
  const d = document.createElement("div");
  d.setAttribute("role", "alert");
  d.style.cssText = "margin:16px auto;max-width:1060px;border:1px solid #e0322a;" +
    "background:rgba(224,50,42,.12);color:#ff4a40;padding:14px 18px;" +
    "font:500 13px/1.6 'JetBrains Mono',monospace;white-space:pre-wrap";
  d.textContent = "This lesson could not start.\n" + title +
    (detail ? "\n\n" + detail : "");
  document.body.prepend(d);
}

(async function () {
  const NS = "http://www.w3.org/2000/svg";

  if (location.protocol === "file:") {
    fatal("Opened as a file:// URL, where the browser blocks loading the " +
          "lesson's data and WebAssembly.",
          "Serve the site instead (any static server works):\n" +
          "    cd physics-lab/public && python3 -m http.server 8000\n" +
          "then open http://localhost:8000/");
    return;
  }

  const base = document.querySelector("script[data-lesson]").dataset.lesson;

  let lesson, wasm, notesHtml;
  try {
    lesson = await (await fetch(base + "/lesson.json")).json();
    notesHtml = lesson.notes
      ? await (await fetch(base + "/" + lesson.notes)).text()
      : "";
    const bytes = await (await fetch(base + "/lesson.wasm")).arrayBuffer();
    const { instance } = await WebAssembly.instantiate(bytes, {});
    wasm = instance.exports;
  } catch (e) {
    fatal("Loading the lesson failed: " + e,
          "If this is a Content-Security-Policy error, script-src needs " +
          "'wasm-unsafe-eval' (set in this site's _headers).");
    return;
  }
  try {

  // ---- scaffold: the whole page from the manifest -------------------------
  const root = document.getElementById("lesson");
  const h = (tag, cls, html) => {
    const e = document.createElement(tag);
    if (cls) e.className = cls;
    if (html !== undefined) e.innerHTML = html;
    return e;
  };

  const header = h("header");
  header.append(
    h("div", "eyebrow", lesson.eyebrow || "Goosethropic Physics"),
    h("h1", "", lesson.title),
    h("p", "lede", lesson.lede || ""));
  root.append(header);

  if (lesson.claims && lesson.claims.length) {
    const c = h("div", "claims");
    for (const cl of lesson.claims) {
      c.append(h("div", "claim-row",
        "<span class='cid'>" + cl.id + "</span> " + cl.text +
        (cl.test ? " <span class='ctest'>" + cl.test + "</span>" : "")));
    }
    root.append(c);
  }

  const stages = h("div", "stages");
  lesson.views.forEach((v, i) => {
    const st = h("div", "stage" + (v.wide ? " wide" : ""));
    if (v.title) {
      st.append(h("div", "stagehead",
        "<h2>" + v.title + "</h2>" +
        (v.law ? "<span class='law'>" + v.law + "</span>" : "")));
    }
    const svg = document.createElementNS(NS, "svg");
    svg.setAttribute("viewBox", "0 0 " + v.viewBox.w + " " + v.viewBox.h);
    svg.setAttribute("role", "img");
    svg.setAttribute("aria-label", lesson.title);
    const g = document.createElementNS(NS, "g");
    g.id = "scene" + i;
    svg.append(g);
    st.append(svg);
    stages.append(st);
  });
  root.append(stages);

  const bar = h("div", "bar");
  const ctlBox = h("div", "");
  ctlBox.id = "controls";
  if (lesson.sweep) {
    ctlBox.append(
      h("div", "",
        "<label class='k'>Playback</label><div class='row'>" +
        "<button id='play'>" + lesson.sweep.label + "</button></div>"),
      h("div", "",
        "<label class='k'>Speed</label>" +
        "<div class='speed' role='group' aria-label='Playback speed'>" +
        "<button data-rate='0.25'>0.25&times;</button>" +
        "<button data-rate='1' aria-pressed='true'>1&times;</button>" +
        "<button data-rate='2'>2&times;</button></div>"));
  }
  bar.append(ctlBox);
  const roBox = h("dl", "");
  roBox.id = "readouts";
  bar.append(roBox);
  root.append(bar);

  if (lesson.legend && lesson.legend.length) {
    const lg = h("div", "panel");
    const row = h("div", "legend");
    for (const item of lesson.legend) {
      const sw = lesson.styles[item.style];
      row.append(h("span", "",
        "<i class='swatch' style='background:var(" + sw.var + ")'></i> " + item.label));
    }
    lg.append(row);
    root.append(lg);
  }

  if (notesHtml) root.append(h("div", "panel", notesHtml));

  if (lesson.tryThis && lesson.tryThis.length) {
    const tp = h("div", "panel");
    tp.append(h("div", "tryhead", "Try this"));
    const ul = h("ul", "trylist");
    for (const t of lesson.tryThis) ul.append(h("li", "", t));
    tp.append(ul);
    root.append(tp);
  }

  root.append(h("footer", "",
    "<a href='../../index.html'>&larr; Physics lab</a>" +
    (lesson.footer ? " &middot; " + lesson.footer : "")));

  // ---- world <-> screen, per view ----------------------------------------
  function mapping(world, vb, uniform, label) {
    const mx = vb.w / (world.x1 - world.x0), my = vb.h / (world.y1 - world.y0);
    if (uniform !== false && Math.abs(mx - my) > 1e-9 * Math.max(mx, my)) {
      throw new Error("runtime: non-uniform world scale in " + label +
        " (" + mx + " vs " + my + ")");
    }
    return {
      sx: x => (x - world.x0) * mx,
      sy: y => vb.h - (y - world.y0) * my,
    };
  }
  const views = lesson.views.map((v, i) => ({
    map: mapping(v.world, v.viewBox, v.uniform, "view " + i),
    scene: document.getElementById("scene" + i),
  }));

  // ---- controls generated from the manifest ------------------------------
  const state = {};
  const updaters = [];
  for (const [key, p] of Object.entries(lesson.params)) {
    state[key] = p.value;
    const wrap = document.createElement("div");
    const lab = document.createElement("label");
    lab.className = "k";
    lab.htmlFor = "p-" + key;
    lab.innerHTML = p.label + ' <span class="val" id="p-' + key + 'lab"></span>';
    const input = document.createElement("input");
    input.type = "range";
    input.id = "p-" + key;
    input.min = p.min; input.max = p.max; input.step = p.step; input.value = p.value;
    const out = lab.querySelector("span");
    const upd = () => {
      state[key] = +input.value;
      out.textContent = (+input.value).toFixed(p.digits ?? 2) + (p.unit ? " " + p.unit : "");
      draw();
    };
    input.addEventListener("input", () => { if (sweep) stopSweep(); upd(); });
    wrap.append(lab, input);
    ctlBox.appendChild(wrap);
    updaters.push(upd);
  }

  // ---- readouts generated from the manifest ------------------------------
  const roEls = [];
  for (const r of lesson.readouts) {
    const d = h("div", "num" + (r.hero ? " hero" : ""),
      "<dt>" + r.label + "</dt><dd>&mdash;</dd>");
    roBox.appendChild(d);
    roEls.push({ slot: r.slot, fmt: r.fmt, el: d.querySelector("dd") });
  }
  const FMT = {
    turns3: v => v.toFixed(3) + " τ",
    fix3: v => v.toFixed(3),
    sci: v => (v === 0 ? "0" : v.toExponential(1)),
  };

  // ---- painting ----------------------------------------------------------
  const styles = lesson.styles;
  function css(st) { return "var(" + styles[st | 0].var + ")"; }
  function el(name, attrs) {
    const e = document.createElementNS(NS, name);
    for (const k in attrs) e.setAttribute(k, attrs[k]);
    return e;
  }

  function paint(buf, n) {
    for (const v of views) v.scene.textContent = "";
    let view = views[0];
    let i = 0;
    while (i < n) {
      const tag = buf[i];
      const { sx, sy } = view.map;
      if (tag === 9) {
        view = views[buf[i + 1] | 0];
        i += 2;
      } else if (tag === 0) {
        view.scene.appendChild(el("circle", { cx: sx(buf[i+1]), cy: sy(buf[i+2]),
          r: 4.5, fill: css(buf[i+3]) }));
        i += 4;
      } else if (tag === 2) {
        const cnt = buf[i + 1] | 0;
        const st = buf[i + 2 + 2 * cnt];
        const s = styles[st | 0];
        let pts = "";
        for (let j = 0; j < cnt; j++) {
          pts += (j ? " " : "") + sx(buf[i + 2 + 2*j]).toFixed(2) + "," +
                 sy(buf[i + 3 + 2*j]).toFixed(2);
        }
        view.scene.appendChild(el("polyline", { points: pts, fill: "none",
          stroke: css(st), "stroke-width": s.width ?? 2,
          "stroke-dasharray": s.dash ? "6 5" : "none",
          "stroke-linejoin": "round", "stroke-linecap": "round" }));
        i += 3 + 2 * cnt;
      } else if (tag === 1 || tag === 3) {
        const [x1, y1, x2, y2, st] = [buf[i+1], buf[i+2], buf[i+3], buf[i+4], buf[i+5]];
        const s = styles[st | 0];
        view.scene.appendChild(el("line", { x1: sx(x1), y1: sy(y1),
          x2: sx(x2), y2: sy(y2), stroke: css(st), "stroke-width": s.width ?? 2,
          "stroke-dasharray": s.dash ? "6 5" : "none", "stroke-linecap": "round" }));
        if (tag === 3) {
          const ang = Math.atan2(sy(y2) - sy(y1), sx(x2) - sx(x1));
          const L = 11, Wd = 4.5;
          const hx = sx(x2), hy = sy(y2);
          view.scene.appendChild(el("path", {
            d: "M " + hx + " " + hy +
               " L " + (hx - L * Math.cos(ang) + Wd * Math.sin(ang)) + " " +
                       (hy - L * Math.sin(ang) - Wd * Math.cos(ang)) +
               " L " + (hx - L * Math.cos(ang) - Wd * Math.sin(ang)) + " " +
                       (hy - L * Math.sin(ang) + Wd * Math.cos(ang)) + " Z",
            fill: css(st) }));
        }
        i += 6;
      } else {
        throw new Error("runtime: unknown prim tag " + tag);
      }
    }
  }

  // ---- the frame: params into wasm memory, prims back --------------------
  const keys = Object.keys(lesson.params);
  function draw() {
    const pv = new Float64Array(wasm.memory.buffer, wasm.params_ptr(), keys.length);
    keys.forEach((k, i) => { pv[i] = state[k] * (lesson.params[k].scale ?? 1); });
    const n = wasm.state_at(keys.length);
    paint(new Float64Array(wasm.memory.buffer, wasm.prims_ptr(), n), n);
    const rd = new Float64Array(wasm.memory.buffer, wasm.readouts_ptr(), 8);
    for (const r of roEls) r.el.textContent = (FMT[r.fmt] || FMT.fix3)(rd[r.slot]);
  }

  // ---- sweep clock -------------------------------------------------------
  let sweep = false, rate = 1, last = null;
  const sw = lesson.sweep;
  const btn = document.getElementById("play");
  function stopSweep() { sweep = false; if (btn) btn.textContent = sw.label; }
  if (sw && btn) {
    btn.addEventListener("click", () => {
      sweep = !sweep;
      btn.textContent = sweep ? "Pause" : sw.label;
    });
    document.querySelectorAll(".speed button").forEach(b =>
      b.addEventListener("click", () => {
        rate = +b.dataset.rate;
        document.querySelectorAll(".speed button").forEach(o =>
          o.setAttribute("aria-pressed", String(o === b)));
      }));
    (function tick(ts) {
      if (last === null) last = ts;
      const dt = Math.min(60, ts - last) / 1000; last = ts;
      if (sweep) {
        const p = lesson.params[sw.param];
        let v = state[sw.param] + sw.rate * dt * rate;
        const span = p.max - p.min;
        v = p.min + ((v - p.min) % span + span) % span;
        state[sw.param] = v;
        const input = document.getElementById("p-" + sw.param);
        input.value = v;
        document.getElementById("p-" + sw.param + "lab").textContent =
          v.toFixed(p.digits ?? 2) + (p.unit ? " " + p.unit : "");
        draw();
      }
      requestAnimationFrame(tick);
    })(performance.now());
  }

  for (const f of updaters) f();
  draw();
  } catch (e) {
    fatal("The lesson loaded but failed while starting: " + e,
          e && e.stack ? String(e.stack).split("\n").slice(0, 3).join("\n") : "");
  }
})();
